'use client';

import { Search, Settings, MoreVertical, Package, Layout } from 'lucide-react';
import { CanvasItem, Proposition, Vendor } from '@/lib/types';

interface PropertiesPanelProps {
    selectedItem: CanvasItem | undefined;
    selectedCount: number;
    propositions: Proposition[];
    vendors: Vendor[];
}

export function PropertiesPanel({ selectedItem, selectedCount, propositions, vendors }: PropertiesPanelProps) {
    return (
        <aside
            className="w-96 flex flex-col z-20"
            style={{
                borderLeft: '1px solid var(--color-border)',
                backgroundColor: 'var(--color-surface)'
            }}
        >
            <div className="flex flex-col h-full">
                <div
                    className="p-6 flex items-center justify-between"
                    style={{ borderBottom: '1px solid var(--color-border)' }}
                >
                    <h2
                        className="text-sm font-bold uppercase tracking-widest flex items-center gap-2"
                        style={{ color: 'var(--color-text)' }}
                    >
                        <Settings
                            className="w-4 h-4"
                            style={{ color: 'var(--color-primary)' }}
                        />
                        Inspector
                    </h2>
                    {selectedCount > 1 && (
                        <div className="px-2 py-1 rounded-lg border bg-blue-500/20 border-blue-500/30">
                            <span className="text-[10px] font-bold text-blue-500">
                                {selectedCount} Selected
                            </span>
                        </div>
                    )}
                    <div
                        className="w-8 h-8 rounded-lg flex items-center justify-center"
                        style={{ backgroundColor: 'var(--color-background-secondary)' }}
                    >
                        <MoreVertical
                            className="w-4 h-4"
                            style={{ color: 'var(--color-text-muted)' }}
                        />
                    </div>
                </div>

                {selectedItem ? (
                    <div className="p-6 space-y-8 animate-in fade-in slide-in-from-right-4 duration-300">
                        <div className="flex items-center gap-4">
                            <div
                                className="w-16 h-16 rounded-2xl border flex items-center justify-center"
                                style={{
                                    backgroundColor: 'var(--color-background-secondary)',
                                    borderColor: 'var(--color-border)'
                                }}
                            >
                                {selectedItem.entityType === 'product' ? (
                                    <Package
                                        className="w-8 h-8"
                                        style={{ color: 'var(--color-primary)' }}
                                    />
                                ) : (
                                    <Layout
                                        className="w-8 h-8"
                                        style={{ color: 'var(--color-secondary)' }}
                                    />
                                )}
                            </div>
                            <div>
                                <h3
                                    className="text-lg font-bold"
                                    style={{ color: 'var(--color-text)' }}
                                >
                                    {selectedItem.data.label}
                                </h3>
                                <p
                                    className="text-xs"
                                    style={{ color: 'var(--color-text-muted)' }}
                                >
                                    {selectedItem.entityType.toUpperCase()}
                                </p>
                            </div>
                        </div>

                        <div className="space-y-4">
                            <div
                                className="p-4 rounded-2xl border"
                                style={{
                                    backgroundColor: 'var(--color-background-secondary)',
                                    borderColor: 'var(--color-border)'
                                }}
                            >
                                <label
                                    className="text-[10px] font-bold uppercase tracking-widest block mb-2"
                                    style={{ color: 'var(--color-text-muted)' }}
                                >
                                    Hierarchy
                                </label>
                                <div className="space-y-3">
                                    <div className="flex items-center justify-between">
                                        <span
                                            className="text-xs"
                                            style={{ color: 'var(--color-text-secondary)' }}
                                        >
                                            Vendor
                                        </span>
                                        <span
                                            className="text-xs font-medium"
                                            style={{ color: 'var(--color-text)' }}
                                        >
                                            {selectedItem.entityType === 'product' ? vendors.find(v => v.id === selectedItem.data.payload?.vendorId)?.name : 'N/A'}
                                        </span>
                                    </div>
                                    <div className="flex items-center justify-between">
                                        <span
                                            className="text-xs"
                                            style={{ color: 'var(--color-text-secondary)' }}
                                        >
                                            Proposition
                                        </span>
                                        <span className="px-2 py-0.5 rounded bg-blue-500/20 text-blue-500 text-[10px] font-bold uppercase">
                                            {selectedItem.entityType === 'product' ? propositions.find(p => p.id === selectedItem.data.payload?.propositionId)?.label : 'Standard'}
                                        </span>
                                    </div>
                                </div>
                            </div>

                            <div
                                className="p-4 rounded-2xl border"
                                style={{
                                    backgroundColor: 'var(--color-background-secondary)',
                                    borderColor: 'var(--color-border)'
                                }}
                            >
                                <label
                                    className="text-[10px] font-bold uppercase tracking-widest block mb-2"
                                    style={{ color: 'var(--color-text-muted)' }}
                                >
                                    Specifications
                                </label>
                                <div
                                    className="text-xs leading-relaxed italic"
                                    style={{ color: 'var(--color-text-secondary)' }}
                                >
                                    Detailed technical specifications and metrics will appear here based on the selected entity profile.
                                </div>
                            </div>
                        </div>

                        <button
                            className="w-full py-3 rounded-xl text-white text-sm font-semibold transition-colors shadow-lg"
                            style={{
                                backgroundColor: 'var(--color-primary)',
                                boxShadow: '0 10px 25px -5px var(--color-primary)'
                            }}
                        >
                            Configure Detailed Design
                        </button>
                    </div>
                ) : (
                    <div className="flex-1 flex flex-col items-center justify-center p-10 text-center">
                        <div
                            className="w-20 h-20 rounded-full flex items-center justify-center mb-6"
                            style={{ backgroundColor: 'var(--color-background-secondary)' }}
                        >
                            <Search
                                className="w-8 h-8"
                                style={{ color: 'var(--color-text-muted)' }}
                            />
                        </div>
                        <h3
                            className="font-medium mb-2"
                            style={{ color: 'var(--color-text-secondary)' }}
                        >
                            No Asset Selected
                        </h3>
                        <p
                            className="text-xs leading-relaxed"
                            style={{ color: 'var(--color-text-muted)' }}
                        >
                            Select an asset on the canvas to view its configuration, hierarchy, and metrics.
                        </p>
                    </div>
                )}
            </div>
        </aside>
    );
}
