'use client';

import { Package, Search } from 'lucide-react';
import { cn } from '@/lib/utils';
import { PropositionType, Proposition, Product, Vendor, Solution } from '@/lib/types';
import { DraggableSidebarItem } from './DraggableSidebarItem';
import { SidebarSection } from './SidebarSection';

interface CanvasSidebarProps {
    searchQuery: string;
    onSearchChange: (query: string) => void;
    selectedProposition: PropositionType | 'all';
    onPropositionChange: (prop: PropositionType | 'all') => void;
    propositions: Proposition[];
    filteredProducts: Product[];
    solutions: Solution[];
    vendors: Vendor[];
    getVendorName: (vendorId: string) => string | undefined;
}

export function CanvasSidebar({
    searchQuery,
    onSearchChange,
    selectedProposition,
    onPropositionChange,
    propositions,
    filteredProducts,
    solutions,
    vendors,
    getVendorName
}: CanvasSidebarProps) {
    return (
        <aside
            className="w-80 flex flex-col z-20"
            style={{
                borderRight: '1px solid var(--color-border)',
                backgroundColor: 'var(--color-surface)'
            }}
        >
            <div className="flex flex-col h-full">
                {/* Header */}
                <div
                    className="p-6"
                    style={{ borderBottom: '1px solid var(--color-border)' }}
                >
                    <div className="flex items-center gap-3 mb-6">
                        <div
                            className="w-10 h-10 rounded-2xl flex items-center justify-center shadow-lg"
                            style={{
                                background: 'linear-gradient(135deg, var(--color-primary), var(--color-secondary))',
                                boxShadow: '0 10px 25px -5px var(--color-primary)'
                            }}
                        >
                            <Package className="w-5 h-5 text-white" />
                        </div>
                        <div>
                            <h1
                                className="text-xl font-bold tracking-tight"
                                style={{ color: 'var(--color-text)' }}
                            >
                                Qanvas
                            </h1>
                            <p
                                className="text-[10px] uppercase tracking-[0.2em] font-medium"
                                style={{ color: 'var(--color-text-muted)' }}
                            >
                                Architecture Engine
                            </p>
                        </div>
                    </div>

                    {/* Search */}
                    <div className="relative group">
                        <Search
                            className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 transition-colors"
                            style={{ color: 'var(--color-text-muted)' }}
                        />
                        <input
                            type="text"
                            placeholder="Search assets..."
                            className="w-full rounded-xl py-2.5 pl-10 pr-4 text-sm focus:outline-none transition-all"
                            style={{
                                backgroundColor: 'var(--color-background-secondary)',
                                border: '1px solid var(--color-border)',
                                color: 'var(--color-text)'
                            }}
                            value={searchQuery}
                            onChange={(e) => onSearchChange(e.target.value)}
                        />
                    </div>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
                    {/* Proposition Filters */}
                    <div className="flex flex-wrap gap-2 mb-6">
                        <button
                            onClick={() => onPropositionChange('all')}
                            className="px-3 py-1.5 rounded-full text-xs font-medium transition-all"
                            style={{
                                backgroundColor: selectedProposition === 'all' ? 'var(--color-primary)' : 'var(--color-background-secondary)',
                                color: selectedProposition === 'all' ? 'white' : 'var(--color-text-muted)'
                            }}
                        >
                            All
                        </button>
                        {propositions.map(prop => (
                            <button
                                key={prop.id}
                                onClick={() => onPropositionChange(prop.id)}
                                className="px-3 py-1.5 rounded-full text-xs font-medium transition-all"
                                style={{
                                    backgroundColor: selectedProposition === prop.id ? 'var(--color-primary)' : 'var(--color-background-secondary)',
                                    color: selectedProposition === prop.id ? 'white' : 'var(--color-text-muted)'
                                }}
                            >
                                {prop.label}
                            </button>
                        ))}
                    </div>

                    {/* Products */}
                    <SidebarSection title="Products Palette">
                        {filteredProducts.map(prod => (
                            <DraggableSidebarItem
                                key={prod.id}
                                id={prod.id}
                                type="product"
                                label={prod.name}
                                data={prod}
                                vendorName={getVendorName(prod.vendorId)}
                            />
                        ))}
                        {filteredProducts.length === 0 && (
                            <div className="p-8 text-center border-2 border-dashed border-white/5 rounded-2xl">
                                <p className="text-xs text-white/20">No products found</p>
                            </div>
                        )}
                    </SidebarSection>

                    {/* Solutions */}
                    <SidebarSection title="Pre-defined Solutions" defaultOpen={false}>
                        {solutions.map(sol => (
                            <DraggableSidebarItem
                                key={sol.id}
                                id={sol.id}
                                type="solution"
                                label={sol.name}
                                data={sol}
                            />
                        ))}
                    </SidebarSection>

                    {/* Vendors */}
                    <SidebarSection title="Vendors" defaultOpen={false}>
                        {vendors.map(v => (
                            <DraggableSidebarItem
                                key={v.id}
                                id={v.id}
                                type="vendor"
                                label={v.name}
                                data={v}
                            />
                        ))}
                    </SidebarSection>
                </div>
            </div>
        </aside>
    );
}
